* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #f1f5f9;
  color: #0f172a;
  min-height: 100vh;
}
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #0f172a;
  color: #fff;
  padding: 14px 18px;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 17px; }
.logo {
  background: #f59e0b; color: #0f172a;
  width: 28px; height: 28px; border-radius: 8px;
  display: grid; place-items: center; font-weight: 900;
}
.cart {
  background: #f59e0b; border: 0; color: #0f172a;
  padding: 8px 14px; border-radius: 10px; font-weight: 700; cursor: pointer;
}
.layout { display: grid; grid-template-columns: 1fr 320px; gap: 18px; padding: 18px; align-items: start; }
h2 { font-size: 18px; margin-bottom: 12px; }
.products { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; }
.product {
  background: #fff; border-radius: 14px; padding: 14px;
  text-align: center; border: 1px solid #e2e8f0;
}
.emoji { font-size: 34px; }
.name { font-weight: 600; font-size: 13px; margin: 6px 0; }
.price { color: #f59e0b; font-weight: 800; margin-bottom: 8px; }
.btn { background: #0f172a; color: #fff; border: 0; padding: 7px 12px; border-radius: 8px; cursor: pointer; font-weight: 600; }
.cart-panel {
  background: #fff; border-radius: 14px; padding: 16px;
  border: 1px solid #e2e8f0; position: sticky; top: 18px;
}
.cart-panel h3 { margin-bottom: 10px; font-size: 16px; }
ul { list-style: none; }
li {
  display: flex; align-items: center; justify-content: space-between;
  gap: 8px; font-size: 13px; padding: 8px 0; border-bottom: 1px solid #e2e8f0;
}
li .name { margin: 0; font-weight: 500; }
li button {
  border: 1px solid #cbd5e1; background: #fff;
  width: 22px; height: 22px; border-radius: 6px; cursor: pointer; font-weight: 700;
}
li .empty { border: 0; color: #94a3b8; }
.total { margin-top: 12px; font-size: 15px; display: flex; justify-content: space-between; }
.checkout {
  width: 100%; background: #22c55e; color: #fff;
  border: 0; padding: 11px; border-radius: 10px; font-weight: 800; cursor: pointer; margin-top: 10px;
}
.toast {
  position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%);
  background: #0f172a; color: #fff; padding: 10px 18px;
  border-radius: 10px; font-size: 13px; z-index: 10;
}
.hidden { display: none; }

const products = [
  { id: 1, name: 'Kaos Polos Premium', price: 85000, emoji: '👕' },
  { id: 2, name: 'Hoodie Oversize', price: 165000, emoji: '🧥' },
  { id: 3, name: 'Tote Bag Kanvas', price: 45000, emoji: '👜' },
  { id: 4, name: 'Topi Snapback', price: 65000, emoji: '🧢' },
  { id: 5, name: 'Botol Minum 500ml', price: 55000, emoji: '🍶' },
  { id: 6, name: 'Gantungan Kunci', price: 15000, emoji: '🔑' }
]
let cart = []
const fmt = (n) => 'Rp ' + n.toLocaleString('id-ID')

const grid = document.getElementById('products')
grid.innerHTML = products.map((p) => `
  <div class="product">
    <span class="emoji">${p.emoji}</span>
    <p class="name">${p.name}</p>
    <p class="price">${fmt(p.price)}</p>
    <button class="btn" onclick="addToCart(${p.id})">Tambah</button>
  </div>`).join('')

function addToCart(id) {
  const p = products.find((x) => x.id === id)
  const item = cart.find((c) => c.id === id)
  if (item) item.qty++
  else cart.push({ ...p, qty: 1 })
  render()
  toast(p.name + ' ditambahkan ke keranjang')
}

function changeQty(id, delta) {
  const item = cart.find((c) => c.id === id)
  if (!item) return
  item.qty += delta
  if (item.qty <= 0) cart = cart.filter((c) => c.id !== id)
  render()
}

function render() {
  document.getElementById('cartCount').textContent = cart.reduce((s, c) => s + c.qty, 0)
  document.getElementById('total').textContent = fmt(cart.reduce((s, c) => s + c.qty * c.price, 0))
  document.getElementById('cartList').innerHTML = cart.length
    ? cart.map((c) => `<li><span class="name">${c.emoji} ${c.name}</span><span><button onclick="changeQty(${c.id},-1)">−</button> ${c.qty} <button onclick="changeQty(${c.id},1)">+</button></span><b>${fmt(c.qty * c.price)}</b></li>`).join('')
    : '<li class="empty">Keranjang masih kosong</li>'
}

document.getElementById('cartBtn').addEventListener('click', () => {
  document.getElementById('cartPanel').classList.toggle('hidden')
})
document.getElementById('checkoutBtn').addEventListener('click', () => {
  if (!cart.length) return toast('Keranjang masih kosong')
  cart = []
  render()
  document.getElementById('cartPanel').classList.add('hidden')
  toast('Checkout berhasil! Terima kasih 🙌')
})

let toastTimer
function toast(msg) {
  const t = document.getElementById('toast')
  t.textContent = msg
  t.classList.remove('hidden')
  clearTimeout(toastTimer)
  toastTimer = setTimeout(() => t.classList.add('hidden'), 2200)
}

render()
